    ],
  }

  const options = styleDescriptions[style] || styleDescriptions.any
  return randomPick(options) || 'A carefully curated outfit combination'
}

/**
 * Apply Pinterest 2026 trend-based outfit combination
 */
function applyTrendBasedOutfit(
  categorized: CategorizedProducts,
  style: OutfitStyle,
  aesthetic?: AestheticCategory,
  colorPalette?: ColorPalette
): Product[] {
  // Convert style to occasion type
  const occasionMap: Record<OutfitStyle, 'work' | 'casual'> = {
    business: 'work',
    casual: 'casual',
    formal: 'casual',
    weekend: 'casual',
    date: 'casual',
    workout: 'casual',
    any: 'casual',
  }

  const occasion = occasionMap[style] || 'casual'

  // Apply trend-based combination rules
  const trendItems = applyTrendBasedCombination(categorized, {
    occasion,
    aesthetic,
    colorPalette,
  })

  return trendItems.length > 0 ? trendItems : []
}

/**
 * Generate a single outfit from categorized products
 * Enhanced with Pinterest 2026 trends support and user preference personalization
 */
export function generateOutfit(
  categorized: CategorizedProducts,
  style: OutfitStyle = 'any',
  gender?: 'men' | 'women',
  options?: {
    aesthetic?: AestheticCategory
    colorPalette?: ColorPalette
    useTrends?: boolean
    userProfile?: UserProfile | null
  }
): Outfit | null {
  const { aesthetic, colorPalette, useTrends = true, userProfile } = options || {}

  // Get user preference context if profile exists
  const userContext: UserPreferenceContext | null = userProfile ? getUserPreferenceContext(userProfile) : null

  // Use user's preferred aesthetics if available, otherwise use provided aesthetic
  let targetAesthetic = aesthetic
  if (userContext && userContext.ageAppropriateAesthetics.length > 0 && !aesthetic) {
    // Use first age-appropriate aesthetic from user preferences
    targetAesthetic = userContext.ageAppropriateAesthetics[0]
  }

  let items: Product[] = []

  // Try Pinterest 2026 trend-based combination first
  if (useTrends && (targetAesthetic || colorPalette || style === 'business' || style === 'casual')) {
    items = applyTrendBasedOutfit(categorized, style, targetAesthetic, colorPalette)

    // Deduplicate categories after trend-based combination
    if (items.length > 0) {
      items = deduplicateOutfitCategories(items, {
        aesthetic,
        colorPalette,
        occasion: style === 'business' ? 'work' : 'casual',
      })
    }
  }

  // Fallback to traditional outfit generation if trend-based didn't work
  if (items.length < 2) {
    // Strategy 1: Women's dress-based outfit
    if (gender === 'women' && categorized.dresses.length > 0) {
      const dress = randomPick(categorized.dresses)
      if (dress) items.push(dress)

      // Add shoes
      const shoes = randomPick(categorized.shoes)
      if (shoes) items.push(shoes)

      // Add accessory
      const accessory = randomPick(categorized.accessories)
      if (accessory) items.push(accessory)
    }
    // Strategy 2: Traditional top + bottom + shoes outfit
    else {
      const top = randomPick(categorized.tops)
      const bottom = randomPick(categorized.bottoms)
      const shoes = randomPick(categorized.shoes)

      if (top) items.push(top)
      if (bottom) items.push(bottom)
      if (shoes) items.push(shoes)

      // Add accessory for variety
      if (Math.random() > 0.5) {
        const accessory = randomPick(categorized.accessories)
        if (accessory) items.push(accessory)
      }
    }

    // Deduplicate categories after fallback strategy
    if (items.length > 0) {
      items = deduplicateOutfitCategories(items, {
        aesthetic,
        colorPalette,
        occasion: style === 'business' ? 'work' : 'casual',
      })
    }
  }

  // Need at least 2 items to make an outfit
  if (items.length < 2) {
    return null
  }

  // Final validation before creating outfit object
  const validationResult = validateOutfitComposition(items)
  if (!validationResult.isValid) {
    console.warn('[OutfitGenerator] Invalid composition detected, applying deduplication:', validationResult.issues)
    items = deduplicateOutfitCategories(items, {
      aesthetic,
      colorPalette,
      occasion: style === 'business' ? 'work' : 'casual',
    })
  }

  const totalPrice = items.reduce((sum, p) => sum + p.price, 0)

  // Detect aesthetic from items if not provided
  const detectedAesthetic = aesthetic || (() => {
    const keywords = items.flatMap(item =>
      `${item.name} ${item.visualDescription || ''}`.toLowerCase().split(/\s+/)
    )
    return detectAestheticFromKeywords(keywords) || undefined
  })()

  // Detect color palette from items if not provided
  const detectedPalette = colorPalette || getDominantPalette(items) || undefined

  // Generate title and personalize with user's name if available
  const baseTitle = generateOutfitTitle(items, style, detectedAesthetic)
  const personalizedTitle = userContext?.userName
    ? personalizeOutfitTitle(baseTitle, userContext.userName)
    : baseTitle

  const outfit: Outfit = {
    id: `outfit-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
    title: personalizedTitle,
    description: generateOutfitDescription(items, style, detectedAesthetic, detectedPalette),
    totalPrice,
    items,
    imageUrl: items[0]?.imageUrl,
    aesthetic: detectedAesthetic,
    colorPalette: detectedPalette,
  }

  // Re-validate to ensure deduplication worked
  const finalValidation = validateOutfitComposition(items)

  console.log('[OutfitGenerator] Generated outfit:', {
    title: outfit.title,
    itemCount: outfit.items.length,
    hasImage: !!outfit.imageUrl,
    aesthetic: outfit.aesthetic,
    colorPalette: outfit.colorPalette,
    colorCoordination: calculateColorCoordination(items),
    validationStatus: finalValidation.isValid ? 'PASSED' : 'FAILED',
  })

  return outfit
}

/**
 * Filter products by gender based on category field with strict validation
 * Enhanced with visual consistency validation to ensure product thumbnails
 * match product descriptions (prevents flat-lay/thumbnail mismatch issue)
 *
 * For women's products:
 * - Category must include "women"
 * - Category must NOT include "men" (unless explicitly "women" is also present)
 * - Product name must NOT include masculine style keywords (oxford shoes, derby, brogue, men's cut)
 * - Product image URL must NOT suggest masculine product (e.g., /oxford/, /derby/ patterns)
 *
 * For men's products:
 * - Category must include "men"
 * - Category must NOT include "women"
 *
 * @param products - Array of products to filter
 * @param gender - Target gender ('men' or 'women')
 * @param options - Additional filtering options
 * @returns Filtered array of products matching the gender criteria
 */
export function filterProductsByGender(
  products: Product[],
  gender: 'men' | 'women',
  options?: { enableVisualValidation?: boolean }
): Product[] {
  const { enableVisualValidation = true } = options || {}
  const masculineFootwearKeywords = ['oxford shoe', 'derby shoe', 'brogue shoe', 'wingtip', "men's dress shoe", "men's oxford", "men's derby"]

  return products.filter((product) => {
    const category = (product as any).category?.toLowerCase() || ''
    const productName = (product.product_name || '').toLowerCase()

    if (gender === 'men') {
      return category.includes('men') && !category.includes('women')
    } else {
      // For women's products: strict validation
      const hasWomenCategory = category.includes('women')
      const hasMenCategory = category.includes('men') && !category.includes('women')
      const hasMasculineFootwear = masculineFootwearKeywords.some(keyword => productName.includes(keyword))

      // Visual consistency validation - check if product image suggests wrong gender
      let hasVisualMismatch = false
      if (enableVisualValidation) {
        // Check if it's footwear and validate visual consistency
        const isFootwear = categorizeProduct(product) === 'shoes'
        if (isFootwear) {
          const imageGender = getImageGenderCategory(product.imageUrl)
          if (imageGender === 'masculine') {
            hasVisualMismatch = true
            console.debug(`[Gender Filter] Visual mismatch detected for footwear:`, {
              name: product.name,
              imageUrl: product.imageUrl,
              imageGender,
              reason: 'Image URL pattern suggests masculine footwear'
            })
          }
        }

        // Full visual consistency check for any product type
        if (!hasVisualMismatch && !isVisuallyConsistentForWomen(product, { enableLogging: false })) {
          hasVisualMismatch = true
          console.debug(`[Gender Filter] Visual consistency check failed:`, {
            name: product.name,
            reason: 'Product visual elements suggest masculine product'
          })
        }
      }

      const isValid = hasWomenCategory && !hasMenCategory && !hasMasculineFootwear && !hasVisualMismatch

      // Debug logging for filtered items
      if (!isValid && (hasMenCategory || hasMasculineFootwear || hasVisualMismatch)) {
        console.debug(`[Gender Filter] Excluded from women's products:`, {
          name: product.product_name || product.name,
          category: category,
          reason: hasMenCategory ? 'men category' : hasMasculineFootwear ? 'masculine footwear keyword' : 'visual mismatch'
        })
      }

      return isValid
    }
  })
}

/**
 * Check if a product is women's appropriate footwear
 * Enhanced with image URL pattern validation to ensure visual consistency
 *
 * Women's footwear includes:
 * - Heels, pumps, stilettos, block heels
 * - Women's loafers (pointed-toe, tassel, gold hardware)
 * - Mules (heeled or flat, backless)
 * - Ballet flats, pointed-toe flats
 * - Slingback heels
 * - Women's sneakers, sandals
 *
 * Excludes masculine footwear:
 * - Oxford shoes, derby shoes, brogues
 * - Wingtips, men's dress shoes
 * - Products with masculine image URL patterns
 *
 * @param product - Product to check
 * @param options - Additional validation options
 * @returns true if the product is women's appropriate footwear
 */
export function isWomenFootwear(
  product: Product,
  options?: { enableVisualValidation?: boolean }
): boolean {
  const { enableVisualValidation = true } = options || {}

  const productName = (product.product_name || product.name || '').toLowerCase()
  const description = (product.product_description || product.visualDescription || '').toLowerCase()
  const combined = `${productName} ${description}`

  // Women's footwear keywords
  const womensFootwear = [
    'heel', 'pump', 'stiletto', 'block heel',
    'women\'s loafer', 'women loafer', 'pointed-toe loafer',
    'mule', 'slingback',
    'ballet flat', 'pointed-toe flat', 'rounded flat',
    'women\'s sneaker', 'women sneaker',
    'sandal', 'women\'s sandal',
    'boot', 'ankle boot', 'knee boot' // women's boots
  ]

  // Masculine footwear keywords (to exclude)
  const masculineFootwear = [
    'oxford shoe', 'derby shoe', 'brogue',
    'wingtip', 'men\'s dress shoe',
    'men\'s oxford', 'men\'s derby',
    'men\'s loafer', 'men loafer' // unless specifically women's
  ]

  // Check if it's masculine footwear (should be excluded)
  const isMasculineText = masculineFootwear.some(keyword => combined.includes(keyword))
  if (isMasculineText) {
    console.debug(`[Footwear Filter] Excluded masculine footwear (text):`, productName)
    return false
  }

  // Check image URL patterns for visual consistency
  if (enableVisualValidation) {
    const imageGender = getImageGenderCategory(product.imageUrl)
    if (imageGender === 'masculine') {
      console.debug(`[Footwear Filter] Excluded footwear due to masculine image URL pattern:`, {
        name: productName,
        imageUrl: product.imageUrl,
        imageGender,
      })
      return false
    }

    // Full visual validation
    const validation = validateProductVisualConsistency(product, { enableLogging: false })
    if (!validation.isConsistent && validation.imageGender === 'masculine') {
      console.debug(`[Footwear Filter] Excluded footwear due to visual mismatch:`, {
        name: productName,
        issues: validation.issues,
      })
      return false
    }
  }

  // Check if it's women's footwear
  const isWomens = womensFootwear.some(keyword => combined.includes(keyword))

  return isWomens
}

/**
 * Generate multiple outfits from product catalog
 * Enhanced with user preference personalization
 */
export function generateOutfits(
  products: Product[],
  options: {
    count?: number
    style?: OutfitStyle
    gender?: 'men' | 'women'
    priceRange?: { min: number; max: number }
    userProfile?: UserProfile | null
  } = {}
): Outfit[] {
  const { count = 5, style = 'any', gender, priceRange, userProfile } = options

  // Get user preference context if profile exists
  const userContext = userProfile ? getUserPreferenceContext(userProfile) : null

  // Use gender from user profile if available, otherwise use provided gender
  const targetGender = userProfile?.gender || gender

  // Filter by gender if specified
  let filteredProducts = targetGender ? filterProductsByGender(products, targetGender) : products

  // Filter by price range if specified
  if (priceRange) {
    filteredProducts = filteredProducts.filter(
      (p) => p.price >= priceRange.min && p.price <= priceRange.max
    )
  }

  // Filter out out-of-stock products
  filteredProducts = filteredProducts.filter((p) => p.availability !== 'out_of_stock')

  // Filter by style/occasion if products have tags
  if (style && style !== 'any') {
    const targetOccasion = style === 'business' ? 'work' : style;
    // Only filter if the product HAS an occasion tag. If not, assume it's versatile (mock Central products usually versatile).
    // Actually, for better accuracy, let's filter those that DO have tags.
    // SFERA items have tags. Central mocks don't.
    // If I enforce strict filtering, Central items (without tags) might disappear if they are not compatible?
    // Let's check matching.
    filteredProducts = filteredProducts.filter(p => {
      if (!p.occasion || p.occasion.length === 0) return true; // Keep products without tags (generic)
      return p.occasion.some(occ => occ === targetOccasion || occ === style);
    });
  }

  const categorized = categorizeProducts(filteredProducts)
  const outfits: Outfit[] = []
  const usedCombinations = new Set<string>() // Track used product combinations

  // Try to generate requested number of outfits
  let attempts = 0
  const maxAttempts = count * 5 // Increased attempts to find uniques

  const usedPrimarySkus = new Set<string>()

  while (outfits.length < count && attempts < maxAttempts) {
    // Pass user profile to outfit generation with preferred aesthetics
    const aestheticOption = userContext?.ageAppropriateAesthetics[0]
    const outfit = generateOutfit(categorized, style, targetGender, {
      aesthetic: aestheticOption,
      userProfile,
    })
    if (outfit && outfit.items.length > 0) {
      // Create a unique signature for this outfit based on product SKUs
      const signature = outfit.items.map(p => p.sku).sort().join('-')
      const primarySku = outfit.items[0].sku // Assume first item is primary (Top/Dress)

      // Check if we've already used this combination OR this primary item
      if (!usedCombinations.has(signature) && !usedPrimarySkus.has(primarySku)) {
        // Check if outfit fits price range
        if (!priceRange || (outfit.totalPrice >= priceRange.min && outfit.totalPrice <= priceRange.max)) {
          outfits.push(outfit)
          usedCombinations.add(signature)
          usedPrimarySkus.add(primarySku)
        }
      }
    }
    attempts++
  }

  return outfits
}

/**
 * Generate men's outfits
 */
export function generateMensOutfits(products: Product[], count: number = 5, style?: OutfitStyle): Outfit[] {
  return generateOutfits(products, { count, style, gender: 'men' })
}

/**
 * Generate women's outfits
 */
export function generateWomensOutfits(products: Product[], count: number = 5, style?: OutfitStyle): Outfit[] {
  return generateOutfits(products, { count, style, gender: 'women' })
}

/**
 * Generate outfit based on query context
 * Enhanced with user preference personalization
 */
export function generateOutfitsFromQuery(
  products: Product[],
  query: string,
  userProfile?: UserProfile | null
): Outfit[] {
  const lowerQuery = query.toLowerCase()

  // Determine gender from query (Default to Women for OOTDay or use user profile)
  let gender: 'men' | 'women' | undefined = userProfile?.gender || 'women'
  if (lowerQuery.includes('men') && !lowerQuery.includes('women')) {
    gender = 'men'
  } else if (lowerQuery.includes('women') || lowerQuery.includes('woman')) {
    gender = 'women'
  }

  // Determine style from query
  let style: OutfitStyle = 'any'
  if (lowerQuery.includes('business') || lowerQuery.includes('work') || lowerQuery.includes('office') || lowerQuery.includes('ทำงาน') || lowerQuery.includes('ประชุม')) {
    style = 'business'
  } else if (lowerQuery.includes('casual') || lowerQuery.includes('everyday') || lowerQuery.includes('relax') || lowerQuery.includes('เที่ยว') || lowerQuery.includes('สบาย') || lowerQuery.includes('ชิล')) {
    style = 'casual'
  } else if (lowerQuery.includes('party') || lowerQuery.includes('formal') || lowerQuery.includes('event') || lowerQuery.includes('งานแต่ง') || lowerQuery.includes('ราตรี')) {
    style = 'formal'
  } else if (lowerQuery.includes('weekend') || lowerQuery.includes('saturday') || lowerQuery.includes('sunday') || lowerQuery.includes('brunch')) {
    style = 'weekend'
  } else if (lowerQuery.includes('date') || lowerQuery.includes('dinner') || lowerQuery.includes('romantic') || lowerQuery.includes('เดท') || lowerQuery.includes('แฟน')) {
    style = 'date'
  } else if (lowerQuery.includes('workout') || lowerQuery.includes('gym') || lowerQuery.includes('sport') || lowerQuery.includes('active') || lowerQuery.includes('ออกกำลังกาย')) {
    style = 'workout'
  }

  return generateOutfits(products, { count: 5, style, gender, userProfile })
}

/**
 * Color Palette Matching Utility
 *
 * Provides color detection and matching functionality based on
 * Pinterest 2026 trending color palettes
 */

import type { Product } from '../types'
import {
  COLOR_PALETTES,
  ColorPalette,
  getNeutralEarthTones,
  getColorPaletteKeywords,
} from './pinterest-2026-trends'

// ============================================================================
// Color Detection
// ============================================================================

/**
 * Extract color keywords from product name and description
 */
export function detectProductColor(product: Product): string[] {
  const text = `${product.name} ${product.visualDescription || ''}`.toLowerCase()
  const colors: string[] = []

  // Check against all known color palette keywords
  const allColorKeywords = new Set<string>()
  Object.values(COLOR_PALETTES).forEach(palette => {
    palette.forEach(color => allColorKeywords.add(color.toLowerCase()))
  })

  // Add common color names
  const commonColors = [
    'white', 'black', 'gray', 'grey', 'beige', 'brown', 'red', 'pink',
    'orange', 'yellow', 'green', 'blue', 'navy', 'purple', 'gold', 'silver',
    'olive', 'taupe', 'cream', 'tan', 'khaki', 'sand', 'camel', 'chocolate',
    'mocha', 'ivory', 'charcoal', 'denim', 'forest'
  ]

  commonColors.forEach(color => allColorKeywords.add(color))

  // Also check product colors array if available
  if (product.colors && Array.isArray(product.colors)) {
    product.colors.forEach(color => {
      const lowerColor = color.toLowerCase()
      colors.push(lowerColor)
      allColorKeywords.add(lowerColor)
    })
  }

  // Detect colors from text
  allColorKeywords.forEach(colorKeyword => {
    // Use word boundary matching to avoid false positives
    const regex = new RegExp(`\\b${colorKeyword}\\b`, 'i')
    if (regex.test(text) && !colors.includes(colorKeyword)) {
      colors.push(colorKeyword)
    }
  })

  return colors
}

/**
 * Determine which trending palette the colors belong to
 */
export function getPaletteCompatibility(colors: string[]): ColorPalette | null {
  if (colors.length === 0) return null

  const lowerColors = colors.map(c => c.toLowerCase())

  // Check each palette for matches
  const paletteMatches: { palette: ColorPalette; score: number }[] = []

  for (const [paletteName, paletteColors] of Object.entries(COLOR_PALETTES)) {
    const matchCount = lowerColors.filter(color =>
      paletteColors.some(pc => pc.toLowerCase() === color || color.includes(pc.toLowerCase()))
    ).length

    if (matchCount > 0) {
      // Calculate match percentage
      const score = matchCount / lowerColors.length
      paletteMatches.push({
        palette: paletteName as ColorPalette,
        score,
      })
    }
  }

  // Return palette with highest match score
  if (paletteMatches.length === 0) return null

  paletteMatches.sort((a, b) => b.score - a.score)
  return paletteMatches[0].palette
}

/**
 * Get all palettes that a product matches
 */
export function getMatchingPalettes(product: Product): ColorPalette[] {
  const colors = detectProductColor(product)
  if (colors.length === 0) return []

  const lowerColors = colors.map(c => c.toLowerCase())
  const matchingPalettes: ColorPalette[] = []

  for (const [paletteName, paletteColors] of Object.entries(COLOR_PALETTES)) {
    const hasMatch = lowerColors.some(color =>
      paletteColors.some(pc => pc.toLowerCase() === color || color.includes(pc.toLowerCase()))
    )

    if (hasMatch) {
      matchingPalettes.push(paletteName as ColorPalette)
    }
  }

  return matchingPalettes
}

// ============================================================================
// Color Compatibility
// ============================================================================

/**
 * Check if two products' colors are compatible based on trending palettes
 */
export function areColorsCompatible(colors1: string[], colors2: string[]): boolean {
  if (colors1.length === 0 || colors2.length === 0) return true // No colors = compatible

  const palette1 = getPaletteCompatibility(colors1)
  const palette2 = getPaletteCompatibility(colors2)

  // If either doesn't match a palette, assume compatible
  if (!palette1 || !palette2) return true

  // Same palette = compatible
  if (palette1 === palette2) return true

  // Check if both are neutral palettes (compatible)
  const neutralPalettes: ColorPalette[] = [
    'neutral-earth-tones',
    'monochromatic-beige',
    'monochromatic-brown',
    'monochromatic-black',
  ]

  const bothNeutral = neutralPalettes.includes(palette1) && neutralPalettes.includes(palette2)
  if (bothNeutral) return true

  // Check if both are work palettes (compatible)
  const workPalettes: ColorPalette[] = [
    'work-olive-black',
    'work-brown-cream',
    'all-black-texture',
  ]

  const bothWork = workPalettes.includes(palette1) && workPalettes.includes(palette2)
  if (bothWork) return true

  // Black goes with everything
  const hasBlack1 = colors1.some(c => c.toLowerCase().includes('black'))
  const hasBlack2 = colors2.some(c => c.toLowerCase().includes('black'))
  if (hasBlack1 || hasBlack2) return true

  // Neutral earth tones go with most things
  const neutralEarthTones = getNeutralEarthTones()
  const isNeutral1 = colors1.some(c =>
    neutralEarthTones.some(n => c.toLowerCase().includes(n.toLowerCase()))
  )
  const isNeutral2 = colors2.some(c =>
    neutralEarthTones.some(n => c.toLowerCase().includes(n.toLowerCase()))
  )
  if (isNeutral1 || isNeutral2) return true

  return false
}

/**
 * Check if a product matches a specific color palette
 */
export function isProductInPalette(product: Product, palette: ColorPalette): boolean {
  const productColors = detectProductColor(product)
  if (productColors.length === 0) return false

  const paletteColors = getColorPaletteKeywords(palette)
  return productColors.some(color =>
    paletteColors.some(pc => color.toLowerCase().includes(pc.toLowerCase()))
  )
}

// ============================================================================
// Monochromatic Matching
// ============================================================================

/**
 * Get the base color from a color string
 */
function getBaseColor(color: string): string {
  const lowerColor = color.toLowerCase()

  // Color family mapping
  const colorFamilies: Record<string, string[]> = {
    beige: ['beige', 'cream', 'tan', 'taupe', 'sand', 'ivory', 'ecru'],
    brown: ['brown', 'chocolate', 'camel', 'coffee', 'mocha', 'cocoa', 'chestnut'],
    blue: ['blue', 'navy', 'indigo', 'denim', 'cobalt', 'azure', 'steel'],
    black: ['black', 'charcoal', 'ebony', 'jet', 'onyx'],
    grey: ['grey', 'gray', 'silver', 'ash'],
    white: ['white', 'ivory', 'cream', 'ecru'],
    green: ['green', 'olive', 'forest', 'hunter', 'emerald'],
    red: ['red', 'burgundy', 'wine', 'crimson'],
    pink: ['pink', 'rose', 'blush'],
  }

  for (const [family, variants] of Object.entries(colorFamilies)) {
    if (variants.some(v => lowerColor.includes(v))) {
      return family
    }
  }

  return lowerColor
}

/**
 * Find products in the same color family for monochrome outfits
 */
export function getMonochromaticMatches(baseColor: string, products: Product[]): Product[] {
  const targetFamily = getBaseColor(baseColor)

  return products.filter(product => {
    const productColors = detectProductColor(product)
    return productColors.some(color => getBaseColor(color) === targetFamily)
  })
}

/**
 * Get products with neutral earth tone colors
 */
export function getNeutralEarthToneProducts(products: Product[]): Product[] {
  const neutralTones = getNeutralEarthTones()

  return products.filter(product => {
    const productColors = detectProductColor(product)
    return productColors.some(color =>
      neutralTones.some(n => color.toLowerCase().includes(n.toLowerCase()))
    )
  })
}

/**
 * Get products matching a specific trending palette
 */
export function getProductsByPalette(products: Product[], palette: ColorPalette): Product[] {
  return products.filter(product => isProductInPalette(product, palette))
}

// ============================================================================
// Outfit Color Coordination
// ============================================================================

/**
 * Score how well products coordinate by color
 */
export function calculateColorCoordination(products: Product[]): number {
  if (products.length < 2) return 1.0

  const productColors = products.map(p => detectProductColor(p))

  // Check if all products have compatible colors
  let compatiblePairs = 0
  let totalPairs = 0

  for (let i = 0; i < productColors.length; i++) {
    for (let j = i + 1; j < productColors.length; j++) {
      totalPairs++
      if (areColorsCompatible(productColors[i], productColors[j])) {
        compatiblePairs++
      }
    }
  }

  return totalPairs > 0 ? compatiblePairs / totalPairs : 1.0
}

/**
 * Get the dominant color palette for an outfit
 */
export function getDominantPalette(products: Product[]): ColorPalette | null {
  const paletteCounts: Partial<Record<ColorPalette, number>> = {}

  products.forEach(product => {
    const palettes = getMatchingPalettes(product)
    palettes.forEach(palette => {
      paletteCounts[palette] = (paletteCounts[palette] || 0) + 1
    })
  })

  const entries = Object.entries(paletteCounts)
  if (entries.length === 0) return null

  entries.sort((a, b) => b[1] - a[1])
  return entries[0][0] as ColorPalette
}

/**
 * Check if outfit follows monochromatic color scheme
 */
export function isMonochromaticOutfit(products: Product[]): boolean {
  if (products.length < 2) return false

  const allColors = products.flatMap(p => detectProductColor(p))
  const colorFamilies = new Set(allColors.map(c => getBaseColor(c)))

  // Monochromatic = 1-2 color families (allowing for slight variation)
  return colorFamilies.size <= 2
}

/**
 * Suggest complementary colors for a given product
 */
export function suggestComplementaryColors(product: Product): string[] {
  const productColors = detectProductColor(product)
  if (productColors.length === 0) return getNeutralEarthTones()

  const palette = getPaletteCompatibility(productColors)
  if (!palette) return getNeutralEarthTones()

  // Return colors from the same palette or compatible palettes
  const compatiblePalettes: ColorPalette[] = [palette]

  // Add compatible palette groups
  const neutralPalettes: ColorPalette[] = [
    'neutral-earth-tones',
    'monochromatic-beige',
    'monochromatic-brown',
  ]

  if (neutralPalettes.includes(palette)) {
    compatiblePalettes.push(...neutralPalettes)
  }

  // Collect all compatible colors
  const suggestions = new Set<string>()
  compatiblePalettes.forEach(p => {
    getColorPaletteKeywords(p).forEach(color => suggestions.add(color))
  })

  return Array.from(suggestions)
}

/**
 * Outfit Combination Rules Engine
 *
 * Implements intelligent outfit combination logic based on Pinterest 2026 trends,
 * including layering rules, occasion-specific styling, and aesthetic matching
 */

import type { Product } from '../types'
import type { OccasionType } from '../types/enums'
import type { CategorizedProducts } from '../outfit-generator'
import {
  AestheticCategory,
  ColorPalette,
  LayeringPattern,
  getLayeringPattern,
  getCasualLayeringPatterns,
  getWorkLayeringPatterns,
  getTrendingBottomStyles,
  getTrendingFootwear,
  getTrendingAccessories,
  getAestheticDefinition,
  AESTHETIC_DEFINITIONS,
} from './pinterest-2026-trends'
import {
  detectProductColor,
  areColorsCompatible,
  isProductInPalette,
  getNeutralEarthToneProducts,
  getProductsByPalette,
} from './color-palette-matcher'
import {
  validateProductVisualConsistency,
  isVisuallyConsistentForWomen,
  getImageGenderCategory,
} from '../utils/product-visual-validator'

// ============================================================================
// Type Definitions
// ============================================================================

export interface LayeringRule {
  pattern: LayeringPattern
  baseLayerProducts: Product[]
  topLayerProducts: Product[]
}

export interface OutfitCompositionRule {
  occasion: OccasionType | 'casual'
  aesthetic?: AestheticCategory
  colorPalette?: ColorPalette
  requiredPieces: {
    top?: boolean
    bottom?: boolean
    outerwear?: boolean
    shoes?: boolean
    accessories?: boolean
  }
  layeringPreference?: 'required' | 'optional' | 'none'
  silhouettePreference?: string[]
}

export interface ValidationResult {
  isValid: boolean
  issues: string[]
  duplicateCategories?: string[]
}

/**
 * Pinterest 2026 Work Outfit Formula:
 * - 1 fitted top (blouse/shirt) OR 1 base layer + 1 blazer
 * - 1 wide-leg/tailored trouser (high-waisted preferred)
 * - 1 footwear (heels/loafers)
 * - 1-2 accessories (bag, belt, jewelry)
 * - Total: 3-5 items
 */

/**
 * Pinterest 2026 Casual Outfit Formula:
 * - 1 top OR 1 base layer + 1 cardigan/sweater
 * - 1 bottom (jeans/pants - wide-leg/baggy preferred)
 * - 1 footwear (platform sneakers/chunky shoes)
 * - 1-2 accessories (structured bag, gold jewelry)
 * - Total: 3-5 items
 */

// ============================================================================
// Product Matching Helpers
// ============================================================================

/**
 * Check if product matches keywords
 */
function productMatchesKeywords(product: Product, keywords: string[]): boolean {
  const text = `${product.name} ${product.visualDescription || ''}`.toLowerCase()
  return keywords.some(keyword => text.includes(keyword.toLowerCase()))
}

/**
 * Check if product is oversized
 */
function isOversized(product: Product): boolean {
  const oversizedKeywords = ['oversized', 'loose', 'baggy', 'relaxed', 'slouchy', 'boyfriend']
  return productMatchesKeywords(product, oversizedKeywords)
}

/**
 * Check if product is fitted
 */
function isFitted(product: Product): boolean {
  const fittedKeywords = ['fitted', 'slim', 'tailored', 'bodysuit', 'tight', 'skinny']
  return productMatchesKeywords(product, fittedKeywords)
}

/**
 * Check if product is wide-leg
 */
function isWideLeg(product: Product): boolean {
  const wideLegKeywords = ['wide-leg', 'wide leg', 'palazzo', 'flare', 'baggy']
  return productMatchesKeywords(product, wideLegKeywords)
}

/**
 * Check if product is high-waisted
 */
function isHighWaisted(product: Product): boolean {
  const highWaistedKeywords = ['high-waisted', 'high waist', 'high rise', 'high-rise']
  return productMatchesKeywords(product, highWaistedKeywords)
}

/**
 * Check if product is structured
 */
function isStructured(product: Product): boolean {
  const structuredKeywords = ['structured', 'tailored', 'blazer', 'jacket', 'tote', 'formal']
  return productMatchesKeywords(product, structuredKeywords)
}

/**
 * Check if product is a platform or chunky shoe
 */
function isPlatformOrChunky(product: Product): boolean {
  const keywords = ['platform', 'chunky', 'thick sole', 'dad sneakers', 'gazelle', 'timberland']
  return productMatchesKeywords(product, keywords)
}

// ============================================================================
// Outfit Validation and Deduplication
// ============================================================================

/**
 * Determine product category for outfit composition validation
 * Maps products to outfit roles: outerwear, top, bottom, dress, shoes, accessory
 */
export function getProductCategory(product: Product): string {
  const text = `${product.name} ${product.visualDescription || ''}`.toLowerCase()

  // Check for outerwear (blazers, jackets, coats, cardigans)
  if (
    text.includes('blazer') ||
    text.includes('jacket') ||
    text.includes('coat') ||
    text.includes('cardigan') ||
    text.includes('cardi') ||
    text.includes('suit jacket')
  ) {
    return 'outerwear'
  }

  // Check for dress (standalone item)
  if (text.includes('dress') || text.includes('กระโปรง')) {
    return 'dress'
  }

  // Check for bottoms (pants, skirts, shorts)
  if (
    text.includes('pants') ||
    text.includes('trousers') ||
    text.includes('jeans') ||
    text.includes('shorts') ||
    text.includes('skirt') ||
    text.includes('กางเกง')
  ) {
    return 'bottom'
  }

  // Check for shoes
  if (
    text.includes('shoe') ||
    text.includes('boot') ||
    text.includes('sneaker') ||
    text.includes('sandal') ||
    text.includes('loafer') ||
    text.includes('heel') ||
    text.includes('รองเท้า')
  ) {
    return 'shoes'
  }

  // Check for bags
  if (
    text.includes('bag') ||
    text.includes('tote') ||
    text.includes('handbag') ||
    text.includes('purse') ||
    text.includes('กระเป๋า')
  ) {
    return 'bag'
  }

  // Check for accessories (jewelry, belts, scarves, hats)
  if (
    text.includes('jewelry') ||
    text.includes('necklace') ||
    text.includes('bracelet') ||
    text.includes('earring') ||
    text.includes('ring') ||
    text.includes('belt') ||
    text.includes('scarf') ||
    text.includes('hat') ||
    text.includes('watch') ||
    text.includes('sunglass') ||
    text.includes('เข็มขัด')
  ) {
    return 'accessory'
  }

  // Default to top for other clothing items
  if (
    text.includes('shirt') ||
    text.includes('blouse') ||
    text.includes('t-shirt') ||
    text.includes('tee') ||
    text.includes('top') ||
    text.includes('sweater') ||
    text.includes('hoodie') ||
    text.includes('เสื้อ')
  ) {
    return 'top'
  }

  return 'other'
}

/**
 * Score product for outfit composition
 * Higher score = better fit for the outfit
 */
export function scoreProductForOutfit(
  product: Product,
  outfitContext: {
    aesthetic?: AestheticCategory
    colorPalette?: ColorPalette
    occasion?: OccasionType | 'casual'
  }
): number {
  let score = 0
  const text = `${product.name} ${product.visualDescription || ''}`.toLowerCase()

  // Price weight (30%): Higher price = better quality
  score += (product.price / 10000) * 30

  // Color match weight (30%): Matches outfit color palette
  if (outfitContext.colorPalette) {
    if (isProductInPalette(product, outfitContext.colorPalette)) {
      score += 30
    }
  }

  // Aesthetic match weight (20%): Matches Pinterest 2026 aesthetic
  if (outfitContext.aesthetic) {
    const definition = getAestheticDefinition(outfitContext.aesthetic)
    if (definition) {
      const matchesKeywords = definition.keywords.some(keyword =>
        text.includes(keyword.toLowerCase())
      )
      if (matchesKeywords) {
        score += 20
      }
    }
  }

  // Formality weight (20%): Appropriate for occasion
  const isWorkOccasion = outfitContext.occasion === 'work'
  if (isWorkOccasion) {
    if (isStructured(product) || isFitted(product)) {
      score += 20
    }
  } else {
    // Casual occasions prefer oversized/relaxed
    if (isOversized(product)) {
      score += 20
    }
  }

  return score
}

/**
 * Deduplicate outfit categories by keeping the best-scoring item per category
 * Ensures only ONE item per category (outerwear, bottom, dress, etc.)
 */
export function deduplicateOutfitCategories(
  items: Product[],
  outfitContext: {
    aesthetic?: AestheticCategory
    colorPalette?: ColorPalette
    occasion?: OccasionType | 'casual'
  } = {}
): Product[] {
  // Group items by category
  const categoryMap = new Map<string, Product[]>()

  for (const item of items) {
    const category = getProductCategory(item)
    if (!categoryMap.has(category)) {
      categoryMap.set(category, [])
    }
    categoryMap.get(category)!.push(item)
  }

  // For each category, keep only the best-scoring item
  const deduplicated: Product[] = []

  for (const [category, products] of Array.from(categoryMap.entries())) {
    if (products.length === 1) {
      // Check for gender-inappropriate items even if only one
      const product = products[0]
      const productCategory = (product as any).category?.toLowerCase() || ''
      const hasMenCategory = productCategory.includes('men') && !productCategory.includes('women')

      if (hasMenCategory) {
        console.warn(`[OutfitValidator] Gender warning for ${category}:`, {
          product: product.name,
          category: productCategory,
          reason: 'men category in women\'s outfit'
        })
      }

      deduplicated.push(product)
    } else if (products.length > 1) {
      // Multiple items in same category - keep the best one
      const scored = products.map(p => ({
        product: p,
        score: scoreProductForOutfit(p, outfitContext),
      }))

      // Sort by score descending
      scored.sort((a, b) => b.score - a.score)

      // Keep the highest scoring item
      const kept = scored[0].product
      const removed = scored.slice(1).map(s => s.product)

      console.log(`[OutfitValidator] Removed duplicate ${category}:`, {
        kept: `${kept.name} (score: ${scored[0].score.toFixed(1)})`,
        removed: removed.map(p => p.name),
      })

      deduplicated.push(kept)
    }
  }

  return deduplicated
}

/**
 * Validate outfit composition according to Pinterest 2026 rules
 * Returns validation result with issues list
 */
export function validateOutfitComposition(items: Product[]): ValidationResult {
  const issues: string[] = []
  const duplicateCategories: string[] = []

  // Count items by category
  const categoryCounts = new Map<string, number>()
  const categoryItems = new Map<string, string[]>()

  for (const item of items) {
    const category = getProductCategory(item)
    categoryCounts.set(category, (categoryCounts.get(category) || 0) + 1)

    if (!categoryItems.has(category)) {
      categoryItems.set(category, [])
    }
    categoryItems.get(category)!.push(item.name)
  }

  // Validate: Maximum ONE outerwear per outfit
  const outerwearCount = categoryCounts.get('outerwear') || 0
  if (outerwearCount > 1) {
    issues.push(`Multiple outerwear items (${outerwearCount}): ${categoryItems.get('outerwear')?.join(', ')}`)
    duplicateCategories.push('outerwear')
  }

  // Validate: Maximum ONE bottom per outfit
  const bottomCount = categoryCounts.get('bottom') || 0
  if (bottomCount > 1) {
    issues.push(`Multiple bottom items (${bottomCount}): ${categoryItems.get('bottom')?.join(', ')}`)
    duplicateCategories.push('bottom')
  }

  // Validate: Maximum ONE dress per outfit (dresses are standalone)
  const dressCount = categoryCounts.get('dress') || 0
  if (dressCount > 1) {
    issues.push(`Multiple dress items (${dressCount}): ${categoryItems.get('dress')?.join(', ')}`)
    duplicateCategories.push('dress')
  }

  // Validate: If dress exists, should not have top+bottom
  if (dressCount > 0 && (categoryCounts.get('top') || 0) > 0) {
    issues.push('Outfit has both dress and top - dresses are standalone items')
  }

  // Validate: Maximum ONE pair of shoes
  const shoesCount = categoryCounts.get('shoes') || 0
  if (shoesCount > 1) {
    issues.push(`Multiple shoes (${shoesCount}): ${categoryItems.get('shoes')?.join(', ')}`)
    duplicateCategories.push('shoes')
  }

  // Validate: Check for masculine footwear in women's outfits (text-based)
  const shoes = items.filter(item => getProductCategory(item) === 'shoes')
  for (const shoe of shoes) {
    const name = (shoe.name || '').toLowerCase()
    const masculineKeywords = ['oxford shoe', 'derby shoe', 'brogue', 'wingtip', "men's dress shoe", "men's oxford"]

    if (masculineKeywords.some(kw => name.includes(kw))) {
      issues.push(`Masculine footwear detected in women's outfit: ${shoe.name}`)
      console.warn('[OutfitValidator] Gender-inappropriate footwear:', {
        product: shoe.name,
        category: getProductCategory(shoe),
        reason: 'masculine style keyword'
      })
    }

    // Visual consistency validation: check if image URL suggests masculine footwear
    const imageGender = getImageGenderCategory(shoe.imageUrl)
    if (imageGender === 'masculine') {
      issues.push(`Footwear image suggests masculine product: ${shoe.name}`)
      console.warn('[OutfitValidator] Visual mismatch detected for footwear:', {
        product: shoe.name,
        imageUrl: shoe.imageUrl,
        imageGender,
        reason: 'Image URL pattern suggests masculine footwear'
      })
    }
  }

  // Full visual consistency check for all items
  for (const item of items) {
    const validation = validateProductVisualConsistency(item, { enableLogging: false })
    if (!validation.isConsistent) {
      issues.push(`Visual inconsistency: ${item.name} - ${validation.issues.join('; ')}`)
    }
  }

  // Validate: Check for men's category in women's outfits
  for (const item of items) {
    const category = (item as any).category?.toLowerCase() || ''
    if (category.includes('men') && !category.includes('women')) {
      issues.push(`Men's product in women's outfit: ${item.name}`)
      console.warn('[OutfitValidator] Gender mismatch:', {
        product: item.name,
        category: category,
        reason: 'men category tag'
      })
    }
  }

  // Log validation result
  if (issues.length > 0) {
    console.warn('[OutfitValidator] Outfit composition validation FAILED:', {
      issues,
      categoryCounts: Object.fromEntries(categoryCounts),
    })
  } else {
    console.log('[OutfitValidator] Outfit validation: PASSED', {
      categoryCounts: Object.fromEntries(categoryCounts),
    })
  }

  return {
    isValid: issues.length === 0,
    issues,
    duplicateCategories: duplicateCategories.length > 0 ? duplicateCategories : undefined,
  }
}

// ============================================================================
// Layering Logic
// ============================================================================

/**
 * Find products suitable for layering based on pattern
 */
export function findLayeringProducts(
  pattern: LayeringPattern,
  categorized: CategorizedProducts
): LayeringRule | null {
  const patternDef = getLayeringPattern(pattern)
  if (!patternDef) return null

  const allTops = [...categorized.tops]

  // Find base layer products
  const baseLayerProducts = allTops.filter(product =>
    productMatchesKeywords(product, patternDef.baseLayer)
  )

  // Find top layer products
  const topLayerProducts = allTops.filter(product =>
    productMatchesKeywords(product, patternDef.topLayer)
  )

  if (baseLayerProducts.length === 0 || topLayerProducts.length === 0) {
    return null
  }

  return {
    pattern,
    baseLayerProducts,
    topLayerProducts,
  }
}

/**
 * Apply layering rules to select layered outfit components
 * Returns array with base layer and optional top layer (if layering is possible)
 */
export function applyLayeringRules(
  occasion: OccasionType | 'casual',
  categorized: CategorizedProducts
): Product[] {
  // Get appropriate layering patterns for occasion
  const isWorkOccasion = occasion === 'work'
  const patterns = isWorkOccasion
    ? getWorkLayeringPatterns()
    : getCasualLayeringPatterns()

  // Try each pattern until we find matching products
  for (const pattern of patterns) {
    const layering = findLayeringProducts(pattern, categorized)
    if (layering) {
      // Pick one from each layer
      const baseLayer = layering.baseLayerProducts[
        Math.floor(Math.random() * layering.baseLayerProducts.length)
      ]
      let topLayer = layering.topLayerProducts[
        Math.floor(Math.random() * layering.topLayerProducts.length)
      ]

      // Ensure baseLayer and topLayer are different items
      if (baseLayer.sku === topLayer.sku && layering.topLayerProducts.length > 1) {
        // Pick a different top layer
        const alternativeTopLayers = layering.topLayerProducts.filter(p => p.sku !== baseLayer.sku)
        if (alternativeTopLayers.length > 0) {
          topLayer = alternativeTopLayers[Math.floor(Math.random() * alternativeTopLayers.length)]
        }
      }

      // Check color compatibility
      const baseColors = detectProductColor(baseLayer)
      const topColors = detectProductColor(topLayer)

      if (areColorsCompatible(baseColors, topColors) && baseLayer.sku !== topLayer.sku) {
        // Check if top layer is outerwear
        const topLayerCategory = getProductCategory(topLayer)
        const hasOuterwear = topLayerCategory === 'outerwear'

        console.log('[OutfitValidator] Layering applied:', {
          baseLayer: baseLayer.name,
          topLayer: topLayer.name,
          hasOuterwear,
        })

        return [baseLayer, topLayer]
      }
    }
  }

  // Fallback: return single top if layering not possible
  if (categorized.tops.length > 0) {
    return [categorized.tops[Math.floor(Math.random() * categorized.tops.length)]]
  }

  return []
}

// ============================================================================
// Casual Trend Rules (Pinterest 2026)
// ============================================================================

/**
 * Apply Pinterest 2026 casual/everyday trend rules
 */
export function applyCasualTrendRules(
  products: CategorizedProducts,
  colorPalette?: ColorPalette
): Product[] {
  const outfit: Product[] = []

  // Filter products by color palette if specified
  let filteredProducts = { ...products }
  if (colorPalette) {
    filteredProducts = {
      tops: getProductsByPalette(products.tops, colorPalette),
      bottoms: getProductsByPalette(products.bottoms, colorPalette),
      shoes: getProductsByPalette(products.shoes, colorPalette),
      dresses: getProductsByPalette(products.dresses, colorPalette),
      accessories: getProductsByPalette(products.accessories, colorPalette),
      other: products.other,
    }
  } else {
    // Default to neutral earth tones for casual
    filteredProducts = {
      tops: getNeutralEarthToneProducts(products.tops),
      bottoms: getNeutralEarthToneProducts(products.bottoms),
      shoes: products.shoes, // Don't filter shoes as strictly
      dresses: getNeutralEarthToneProducts(products.dresses),
      accessories: products.accessories,
      other: products.other,
    }
  }

  // Pinterest Casual Trend: Oversized layering
  const layeredTops = applyLayeringRules('casual', filteredProducts)
  let hasOuterwear = false

  if (layeredTops.length > 0) {
    outfit.push(...layeredTops)

    // Check if layering includes outerwear
    hasOuterwear = layeredTops.some(item => getProductCategory(item) === 'outerwear')
  } else {
    // Fallback: single oversized top
    const oversizedTops = filteredProducts.tops.filter(isOversized)
    if (oversizedTops.length > 0) {
      outfit.push(oversizedTops[Math.floor(Math.random() * oversizedTops.length)])
    } else if (filteredProducts.tops.length > 0) {
      outfit.push(filteredProducts.tops[Math.floor(Math.random() * filteredProducts.tops.length)])
    }
  }

  // Pinterest Casual Trend: Baggy/wide-leg bottoms
  const wideLegBottoms = filteredProducts.bottoms.filter(isWideLeg)
  const baggyBottoms = filteredProducts.bottoms.filter(product =>
    productMatchesKeywords(product, ['baggy', 'loose', 'relaxed'])
  )

  const trendyBottoms = [...wideLegBottoms, ...baggyBottoms]
  if (trendyBottoms.length > 0) {
    outfit.push(trendyBottoms[Math.floor(Math.random() * trendyBottoms.length)])
  } else if (filteredProducts.bottoms.length > 0) {
    outfit.push(filteredProducts.bottoms[Math.floor(Math.random() * filteredProducts.bottoms.length)])
  }

  // Pinterest Casual Trend: Platform sneakers or chunky footwear
  const platformShoes = filteredProducts.shoes.filter(isPlatformOrChunky)
  if (platformShoes.length > 0) {
    outfit.push(platformShoes[Math.floor(Math.random() * platformShoes.length)])
  } else if (filteredProducts.shoes.length > 0) {
    outfit.push(filteredProducts.shoes[Math.floor(Math.random() * filteredProducts.shoes.length)])
  }

  // Pinterest Casual Trend: Black structured bag or gold jewelry
  // Only add if we don't already have outerwear from layering
  const structuredBags = filteredProducts.accessories.filter(product =>
    productMatchesKeywords(product, ['bag', 'tote', 'handbag', 'structured', 'black'])
  )
  const goldJewelry = filteredProducts.accessories.filter(product =>
    productMatchesKeywords(product, ['jewelry', 'necklace', 'gold', 'chain', 'layered'])
  )

  const trendyAccessories = [...structuredBags, ...goldJewelry]
  if (trendyAccessories.length > 0) {
    outfit.push(trendyAccessories[Math.floor(Math.random() * trendyAccessories.length)])
  }

  // Validate and deduplicate before returning
  const validation = validateOutfitComposition(outfit)
  if (!validation.isValid) {
    console.warn('[OutfitValidator] Casual outfit has duplicates, deduplicating...')
    return deduplicateOutfitCategories(outfit, { colorPalette })
  }

  console.log('[OutfitValidator] Casual outfit composition:', {
    itemCount: outfit.length,
    hasLayering: layeredTops.length > 1,
    hasOuterwear,
  })

  return outfit
}

// ============================================================================
// Work/Office Trend Rules (Pinterest 2026)
// ============================================================================

/**
 * Apply Pinterest 2026 work/office trend rules
 */
export function applyWorkTrendRules(products: CategorizedProducts): Product[] {
  const outfit: Product[] = []

  // Filter for work-appropriate color palettes
  const workPalettes: ColorPalette[] = ['work-olive-black', 'work-brown-cream', 'all-black-texture']
  let workColoredProducts: Product[] = []

  workPalettes.forEach(palette => {
    workColoredProducts = [
      ...workColoredProducts,
      ...getProductsByPalette([...products.tops, ...products.bottoms], palette),
    ]
  })

  // If no work-colored products, use neutral earth tones
  if (workColoredProducts.length === 0) {
    workColoredProducts = getNeutralEarthToneProducts([...products.tops, ...products.bottoms])
  }

  const workTops = workColoredProducts.filter(p =>
    products.tops.some(t => t.sku === p.sku)
  )
  const workBottoms = workColoredProducts.filter(p =>
    products.bottoms.some(b => b.sku === p.sku)
  )

  // Pinterest Work Trend: Fitted top
  const fittedTops = workTops.filter(isFitted)
  if (fittedTops.length > 0) {
    outfit.push(fittedTops[Math.floor(Math.random() * fittedTops.length)])
  } else if (workTops.length > 0) {
    outfit.push(workTops[Math.floor(Math.random() * workTops.length)])
  } else if (products.tops.length > 0) {
    outfit.push(products.tops[Math.floor(Math.random() * products.tops.length)])
  }

  // Pinterest Work Trend: Wide-leg, high-waisted trousers
  const wideLegBottoms = workBottoms.filter(isWideLeg)
  const highWaistedBottoms = workBottoms.filter(isHighWaisted)
  const idealBottoms = wideLegBottoms.filter(isHighWaisted)

  if (idealBottoms.length > 0) {
    outfit.push(idealBottoms[Math.floor(Math.random() * idealBottoms.length)])
  } else if (wideLegBottoms.length > 0) {
    outfit.push(wideLegBottoms[Math.floor(Math.random() * wideLegBottoms.length)])
  } else if (highWaistedBottoms.length > 0) {
    outfit.push(highWaistedBottoms[Math.floor(Math.random() * highWaistedBottoms.length)])
  } else if (workBottoms.length > 0) {
    outfit.push(workBottoms[Math.floor(Math.random() * workBottoms.length)])
  } else if (products.bottoms.length > 0) {
    outfit.push(products.bottoms[Math.floor(Math.random() * products.bottoms.length)])
  }

  // Pinterest Work Trend: Blazer or cardigan layering (ONE outerwear only)
  // 70% blazer, 30% cardigan for work
  const blazers = products.tops.filter(product =>
    productMatchesKeywords(product, ['blazer', 'jacket', 'suit jacket', 'structured'])
  )
  const cardigans = products.tops.filter(product =>
    productMatchesKeywords(product, ['cardigan', 'cardi', 'open front', 'knit jacket'])
  )

  // Choose either blazer OR cardigan, not both
  let layerPiece: Product | undefined
  const shouldUseBlazer = Math.random() < 0.7 // 70% chance for blazer

  if (shouldUseBlazer && blazers.length > 0) {
    layerPiece = blazers[Math.floor(Math.random() * blazers.length)]
  } else if (cardigans.length > 0) {
    layerPiece = cardigans[Math.floor(Math.random() * cardigans.length)]
  } else if (blazers.length > 0) {
    // Fallback to blazer if no cardigans available
    layerPiece = blazers[Math.floor(Math.random() * blazers.length)]
  }

  // Add the selected outerwear if color compatible
  if (layerPiece && outfit.length > 0) {
    // Check color compatibility with existing outfit
    const outfitColors = outfit.flatMap(p => detectProductColor(p))
    const layerColors = detectProductColor(layerPiece)

    if (areColorsCompatible(outfitColors, layerColors)) {
      outfit.push(layerPiece)
      console.log('[OutfitValidator] Added work outerwear:', layerPiece.name)
    }
  }

  // Pinterest Work Trend: Structured leather tote
  const structuredTotes = products.accessories.filter(product =>
    productMatchesKeywords(product, ['tote', 'bag', 'leather', 'structured', 'work bag'])
  )

  if (structuredTotes.length > 0) {
    outfit.push(structuredTotes[Math.floor(Math.random() * structuredTotes.length)])
  }

  // Pinterest Work Trend: Women's appropriate footwear
  // Priority: heels, loafers, mules, pointed-toe flats
  // Exclude: oxford shoes, derby shoes, brogues (masculine styles)
  if (products.shoes.length > 0) {
    const womensWorkFootwear = products.shoes.filter(shoe => {
      const name = (shoe.name || '').toLowerCase()
      const desc = (shoe.visualDescription || '').toLowerCase()
      const combined = `${name} ${desc}`

      // Exclude masculine footwear
      const masculineKeywords = ['oxford shoe', 'derby shoe', 'brogue', 'wingtip', "men's dress shoe", "men's oxford", "men's derby"]
      const isMasculine = masculineKeywords.some(kw => combined.includes(kw))

      if (isMasculine) {
        console.debug('[Work Outfit] Excluded masculine footwear:', shoe.name)
        return false
      }

      // Prefer women's work-appropriate footwear
      const womensWorkKeywords = [
        'heel', 'pump', 'loafer', 'mule',
        'pointed-toe', 'slingback', 'block heel',
        'women\'s', 'ladies'
      ]
      const isWomensWork = womensWorkKeywords.some(kw => combined.includes(kw))

      return isWomensWork || !isMasculine // Include if women's style or not masculine
    })

    if (womensWorkFootwear.length > 0) {
      outfit.push(womensWorkFootwear[Math.floor(Math.random() * womensWorkFootwear.length)])
      console.log('[Work Outfit] Added women\'s footwear:', womensWorkFootwear[womensWorkFootwear.length - 1].name)
    } else {
      // Fallback to any shoe if no specific women's work footwear found
      outfit.push(products.shoes[Math.floor(Math.random() * products.shoes.length)])
      console.warn('[Work Outfit] No women\'s work footwear found, using fallback shoe')
    }
  }

  // Validate and deduplicate before returning
  const validation = validateOutfitComposition(outfit)
  if (!validation.isValid) {
    console.warn('[OutfitValidator] Work outfit has duplicates, deduplicating...')
    return deduplicateOutfitCategories(outfit, { occasion: 'work' })
  }

  console.log('[OutfitValidator] Work outfit composition:', {
    itemCount: outfit.length,
    outerwearType: layerPiece ? getProductCategory(layerPiece) : 'none',
  })

  return outfit
}

// ============================================================================
// Aesthetic-Based Filtering
// ============================================================================

/**
 * Filter products by aesthetic compatibility
 */
export function getAestheticCompatibleProducts(
  aesthetic: AestheticCategory,
  products: Product[]
): Product[] {
  const definition = getAestheticDefinition(aesthetic)
  if (!definition) return products

  return products.filter(product => {
    const text = `${product.name} ${product.visualDescription || ''}`.toLowerCase()

    // Check if product matches aesthetic keywords
    const matchesKeywords = definition.keywords.some(keyword =>
      text.includes(keyword.toLowerCase())
    )

    // Check if product matches aesthetic color palettes
    const productColors = detectProductColor(product)
    const matchesPalette = definition.colorPalettes.some(palette =>
      isProductInPalette(product, palette)
    )

    return matchesKeywords || matchesPalette
  })
}

/**
 * Apply aesthetic-based outfit composition
 */
export function applyAestheticRules(
  aesthetic: AestheticCategory,
  products: CategorizedProducts,
  occasion?: OccasionType | 'casual'
): Product[] {
  const definition = getAestheticDefinition(aesthetic)
  if (!definition) return []

  // Filter all products by aesthetic
  const aestheticProducts: CategorizedProducts = {
    tops: getAestheticCompatibleProducts(aesthetic, products.tops),
    bottoms: getAestheticCompatibleProducts(aesthetic, products.bottoms),
    shoes: getAestheticCompatibleProducts(aesthetic, products.shoes),
    dresses: getAestheticCompatibleProducts(aesthetic, products.dresses),
    accessories: getAestheticCompatibleProducts(aesthetic, products.accessories),
    other: products.other,
  }

  // Apply occasion-specific rules with aesthetic filtering
  switch (aesthetic) {
    case 'street-style':
    case 'casual-chic':
    case 'clean-girl':
    case 'scandinavian-minimal':
      // Use casual trend rules with aesthetic products
      return applyCasualTrendRules(aestheticProducts)

    case 'corporate-chic':
    case 'quiet-luxury':
    case 'minimalist-office':
      // Use work trend rules with aesthetic products
      return applyWorkTrendRules(aestheticProducts)

    case 'dark-academia':
      // Brown-focused layered look
      const brownProducts: CategorizedProducts = {
        tops: getProductsByPalette(aestheticProducts.tops, 'monochromatic-brown'),
        bottoms: getProductsByPalette(aestheticProducts.bottoms, 'monochromatic-brown'),
        shoes: aestheticProducts.shoes,
        dresses: getProductsByPalette(aestheticProducts.dresses, 'monochromatic-brown'),
        accessories: aestheticProducts.accessories,
        other: aestheticProducts.other,
      }
      return applyCasualTrendRules(brownProducts, 'monochromatic-brown')

    case 'y2k-revival':
      // Colorful, playful combinations
      return applyCasualTrendRules(aestheticProducts)

    default:
      return applyCasualTrendRules(aestheticProducts)
  }
}

// ============================================================================
// Main Combination Engine
// ============================================================================

/**
 * Apply trend-based outfit combination rules
 * Enhanced with user preference support
 */
export function applyTrendBasedCombination(
  products: CategorizedProducts,
  options: {
    occasion?: OccasionType | 'casual'
    aesthetic?: AestheticCategory
    colorPalette?: ColorPalette
    userPreferredAesthetics?: AestheticCategory[]
  } = {}
): Product[] {
  const { occasion = 'casual', aesthetic, colorPalette, userPreferredAesthetics } = options

  // If user has preferred aesthetics and no specific aesthetic is provided, use first preference
  const targetAesthetic = aesthetic || (userPreferredAesthetics && userPreferredAesthetics.length > 0 ? userPreferredAesthetics[0] : undefined)

  // If aesthetic is specified (or derived from user preferences), use aesthetic-based rules
  if (targetAesthetic) {
    return applyAestheticRules(targetAesthetic, products, occasion)
  }

  // Otherwise, use occasion-based rules
  const isWorkOccasion = occasion === 'work'
  if (isWorkOccasion) {
    return applyWorkTrendRules(products)
  }

  return applyCasualTrendRules(products, colorPalette)
}

