 */
export type ProductCategory = 'tops' | 'bottoms' | 'shoes' | 'dresses' | 'accessories' | 'other'

export interface CategorizedProducts {
  tops: Product[]
  bottoms: Product[]
  shoes: Product[]
  dresses: Product[]
  accessories: Product[]
  other: Product[]
}

/**
 * Outfit style templates
